// Original educational content (English edition). Not ISACA text.
window.COBIT_CONTROLS_EN = window.COBIT_CONTROLS_EN || [];
window.COBIT_CONTROLS_EN.push(...
[
{"objective":"APO08","purpose":"The relationship between IT and the business units is the essential bridge that directs technology investments toward real business needs. Poorly managed relationships lead to misprioritized projects, shadow IT and diminished trust in IT services. This objective aims for both parties to work on the basis of a common language, mutual trust and transparent communication.","auditFocus":"The auditor verifies that business expectations are systematically gathered and reflected in IT priorities and that relationship owners are clearly defined. The auditor also looks for evidence that feedback from business units is measured and translated into concrete service improvements.","keyRisks":["IT investments that do not deliver value because business needs are misunderstood","Proliferation of uncontrolled solutions outside IT (shadow IT)","Conflicting priorities and wasted resources due to a lack of communication"],"practices":[
{"code":"APO08.01","name":"Understand business expectations.","title":"Understanding what the business units expect from IT","expectation":"Business strategy, priorities and the issues faced by business units are gathered through regular meetings, demand records and planning sessions conducted by relationship managers or equivalent roles. The gathered expectations are documented, confirmed by the business owner and updated at intervals defined by the organization or upon significant business changes.","design":"Evaluate whether a process exists that defines through which channels, by whom and in what format expectations are gathered, and how this information feeds into IT planning.","operating":"List the key business units active during the period; for units selected based on risk and size, inspect whether expectation records are current and approved by the business owner.","evidence":["Needs and expectations analysis documents by business unit","Business relationship meeting minutes and attendee lists","Demand inventory for the planning period","Business owner approval emails or signed summaries"],"findings":["Expectations are communicated only verbally; no documented and approved record exists.","Expectation information that has not been updated for an extended period is used for some critical business units."],"iso":[],"clauses":["4.2"],"itgc":""},
{"code":"APO08.02","name":"Align I&T strategy with business expectations and identify opportunities for IT to enhance the business.","title":"Linking IT strategy to business expectations and identifying improvement opportunities","expectation":"IT management explicitly links the gathered business expectations to the IT roadmap and portfolio priorities; the value that new technologies could add to business processes is evaluated jointly with the business units. Alignment decisions and their rationale are recorded in governance forums defined by the organization (e.g., IT steering committee).","design":"Inspect whether a mechanism providing traceability between business objectives and IT initiatives (mapping matrix, portfolio evaluation criteria) is defined.","operating":"For a risk-based selection of IT initiatives approved during the period, verify that each is linked to the relevant business objective and that its rationale is documented in committee decisions.","evidence":["Business objective to IT initiative mapping table","IT steering committee agendas and decisions","Opportunity assessment notes or draft business cases","Current IT roadmap"],"findings":["For some approved projects, the business objective they serve cannot be demonstrated.","Technology opportunities proposed by business units are not recorded and therefore fall outside the evaluation process."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO08.03","name":"Manage the business relationship.","title":"Managing the business relationship: ownership, points of contact and escalation","expectation":"For each significant business unit, there is a designated relationship owner on the IT side and a counterpart on the business side; roles and authorities are documented. Requests, complaints and disputes are received through a defined channel, assigned an owner and tracked through to closure.","design":"Evaluate whether a role model or procedure exists that defines the assignment of relationship owners, the escalation path and the dispute resolution method.","operating":"Check that the mapping of business units to relationship owners is current; for escalation and complaint records selected from the period, inspect whether they were assigned an owner and resolved.","evidence":["Relationship manager assignment list or organization chart","Role descriptions and RACI matrix","Complaint and escalation records","Periodic relationship review notes"],"findings":["Following an organizational change, the IT point of contact for some business units has remained undefined.","Escalations from business units are handled without being recorded, and their closure status cannot be tracked."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO08.04","name":"Coordinate and communicate.","title":"Coordinating and communicating between IT and the business units","expectation":"IT informs business units in a timely manner about planned changes, outages, project status and key decisions in accordance with a communication plan defined by the organization. Shared calendars, dependencies and priority conflicts are addressed in regular coordination meetings.","design":"Inspect whether a communication plan exists and is current, defining which information is communicated to whom, through which channel and upon which trigger.","operating":"For significant events and changes selected from the period, compare the timing and content of the notifications sent to business units against the communication plan.","evidence":["IT communication plan","Sample outage and change notifications","Coordination meeting minutes","Shared change and release calendar"],"findings":["Planned outages are communicated late or incompletely to the affected business units.","Where multiple projects affect the same business unit, no record of coordination exists."],"iso":[],"clauses":["7.4"],"itgc":""},
{"code":"APO08.05","name":"Provide input to the continual improvement of services.","title":"Feeding business feedback into service improvement","expectation":"User satisfaction surveys, service review meetings and complaint analyses are performed regularly; the results are converted into improvement proposals with designated owners. The loop is closed by reporting the status of the proposals back to the business units.","design":"Evaluate whether a defined flow exists from the collection of feedback, through its analysis, to its conversion into improvement records.","operating":"Review satisfaction measurements and complaint trends for the period; verify that selected improvement proposals were included in an action plan and tracked.","evidence":["Satisfaction survey results and analyses","Continual service improvement register","Service review meeting minutes","Evidence of closure of improvement actions"],"findings":["Survey results are reported but are not translated into concrete improvement actions.","Items in the improvement register have no defined owner or target date."],"iso":[],"clauses":[],"itgc":""}
]},
{"objective":"APO09","purpose":"When the scope, quality level and responsibilities of IT services are not clarified through written agreements, business units do not know what to expect and IT does not know what it has committed to. This objective ensures that services are defined, cataloged and managed through measurable service levels. As a result, discussions about performance are based on data rather than perception.","auditFocus":"The auditor tests whether the services supporting critical business processes are included in the catalog and defined with measurable targets. The auditor verifies through recalculation that reported service level data is consistent with the source systems and reviews the follow-up of breaches.","keyRisks":["Misaligned expectations due to the absence of defined service levels for critical services","Service level reports prepared using selective or inaccurate data","External supplier contracts that do not support internal service commitments"],"practices":[
{"code":"APO09.01","name":"Identify I&T services.","title":"Identifying IT services and linking them to business processes","expectation":"The organization defines the IT services it provides in terms that business units can understand and identifies which business processes each service supports. The service list is reviewed at intervals defined by the organization in light of new needs and technology changes.","design":"Inspect whether the criteria for identifying services (supported business process, user group, criticality) and service ownership are defined.","operating":"Using a sample selected from the list of critical business processes, verify that the related IT service is defined and that a service owner has been assigned.","evidence":["Service definition documents","Business process to IT service mapping","Service owner assignment records","Service review meeting notes"],"findings":["Some critical applications are not defined as services and their owners are unclear.","Service definitions consist only of technical component lists and do not provide a meaningful description in terms of business outcomes."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO09.02","name":"Catalog I&T-enabled services.","title":"Building and maintaining the service catalog","expectation":"A current service catalog accessible to users exists, showing the scope of services, the access route, support hours and the request method. Catalog changes are made in a controlled manner and are linked to the service introduction and retirement processes.","design":"Evaluate whether responsibility for updating the catalog and the triggers for changes (new service, service retirement, scope change) are defined.","operating":"Compare the list of services put into production or retired during the period with the catalog to check consistency.","evidence":["Published service catalog (portal screenshot or export)","Catalog change history","Service introduction and retirement records"],"findings":["Retired services still appear as active in the catalog.","Support hours and request channels are not specified in the catalog."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO09.03","name":"Define and prepare service agreements.","title":"Agreeing measurable service levels with the business","expectation":"For critical services, service level agreements (SLAs) agreed with the business owner exist, covering availability, response and resolution times, support hours and the responsibilities of the parties, together with internal operational level agreements (OLAs) where needed. Target values are defined by the organization; the measurement method and data source are clearly defined.","design":"Evaluate whether the SLA template covers measurable targets, the measurement method, exclusions and reporting frequency, and whether it is aligned with the underlying supplier contracts.","operating":"For a risk-based selection of critical services, inspect whether an approved SLA exists, whether the targets are measurable and whether the related OLA and supplier contract support these targets.","evidence":["Approved SLA and OLA documents","Business owner approval records","Service level section of the related supplier contract","Metric definition cards"],"findings":["The availability target in the SLA is higher than the level committed in the underlying supplier contract.","Some SLAs do not define the measurement method or data source."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO09.04","name":"Monitor and report service levels.","title":"Measuring service levels from reliable data and reporting them to the business","expectation":"Service level performance is measured using data from monitoring tools and from incident and request management systems, and is reported to business units at intervals defined by the organization. Root cause analysis is performed for target breaches and corrective actions are tracked.","design":"Evaluate whether a reporting process exists under which reported metrics are generated from automated or controlled data sources and manual adjustments require approval.","operating":"For selected reporting periods, reperform the calculation of the reported values using raw data extracted from the source system; verify that breaches are linked to action records.","evidence":["Periodic SLA performance reports","Incident and request data extracts from the source system","Root cause analyses for breaches","Service review meeting minutes"],"findings":["Resolution times in the report are calculated by deducting time spent in “on hold” status using an undefined rule.","No root cause analysis has been performed for recurring SLA breaches."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO09.05","name":"Review service agreements and contracts.","title":"Periodically reviewing service agreements and underpinning contracts","expectation":"SLAs and the supplier contracts that underpin them are reviewed at intervals defined by the organization, or upon significant changes, taking into account changes in business needs and actual performance. The outcome of each review is recorded as a decision either to update or to continue unchanged.","design":"Evaluate whether the review schedule, responsible parties and triggers are defined.","operating":"Inspect the most recent review dates and outcome decisions for records selected from the SLA and contract inventory; identify those whose review is overdue.","evidence":["SLA and contract inventory with review dates","Review meeting notes","Revised SLA versions and approvals"],"findings":["Some SLAs have not been updated for an extended period and do not reflect the current service architecture.","Internal SLA targets were not considered when the supplier contract was renewed."],"iso":["5.22"],"clauses":[],"itgc":""}
]},
{"objective":"APO10","purpose":"Organizations are increasingly dependent on vendors for infrastructure, software, cloud and support services. When vendor selection, contract terms and performance monitoring are weak, cost, service quality and information security risks directly affect the organization. This objective aims to manage vendor relationships in a controlled and risk-aware manner throughout their life cycle.","auditFocus":"The auditor tests whether critical vendors are included in a complete inventory, whether contracts include security, right-to-audit and exit provisions, and whether risk assessments are performed. The auditor also verifies that vendor performance and independent assurance reports are evaluated regularly and that exceptions are followed up.","keyRisks":["A security breach or outage at a critical vendor halting the organization's services","Absence of right-to-audit, data return and exit provisions in contracts","Excessive dependence on vendors and late detection of performance deterioration"],"practices":[
{"code":"APO10.01","name":"Identify and evaluate vendor relationships and contracts.","title":"Identifying and classifying vendor relationships and contracts","expectation":"The organization maintains all IT-related vendors and contracts in a central inventory; vendors are classified by criticality, type of data accessed and level of dependency. The classification determines the intensity of oversight to be applied and is updated at intervals defined by the organization.","design":"Evaluate whether the scope of the vendor inventory, the classification criteria and the oversight requirements differentiated by class are defined.","operating":"Test completeness by comparing IT expenditure in purchasing and payment records against the vendor inventory; inspect whether the classification of selected vendors is consistent with the criteria.","evidence":["Vendor and contract inventory","Criticality classification criteria and results","Vendor list extracted from purchasing and payment records","Inventory update records"],"findings":["Some cloud service providers appearing in payment records are not included in the vendor inventory.","Some vendors processing personal data have been assigned a low criticality class."],"iso":["5.19","5.23"],"clauses":[],"itgc":""},
{"code":"APO10.02","name":"Select vendors.","title":"Selecting vendors and performing pre-contract assessment","expectation":"Vendors are selected through a transparent evaluation against predefined technical, commercial, security and continuity criteria, and conflict-of-interest checks are applied. Contracts are finalized with input from the legal and security functions so that they include service levels, information security obligations, the right to audit, use of subcontractors and exit provisions.","design":"Inspect whether the selection procedure includes evaluation criteria, approval authorities and a security and continuity assessment as mandatory steps.","operating":"For a risk-based selection of new contracts signed during the period, inspect the evaluation matrix, the approvals and the presence of mandatory clauses in the contract.","evidence":["Bid evaluation matrices","Purchasing approval records","Preliminary security assessment or questionnaire results","Security and right-to-audit clauses of signed contracts"],"findings":["Some vendors were selected without a security assessment on the grounds of urgent need.","Contracts contain no clauses on the return and destruction of data upon termination of the relationship."],"iso":["5.19","5.20"],"clauses":[],"itgc":""},
{"code":"APO10.03","name":"Manage vendor relationships and contracts.","title":"Managing vendor relationships and the contract life cycle","expectation":"An internal contract and relationship owner is designated for each critical vendor; contract amendments, renewals and terminations are managed in a controlled manner. Vendor personnel access to the organization's systems is limited to what is needed; upon termination of the relationship, the removal of access and the return of data are tracked.","design":"Evaluate whether the contract life cycle steps (renewal alerts, amendment approval, termination checklist) and vendor access management are defined.","operating":"For contracts selected from those that expired or changed during the period, inspect evidence of access removal and data return; compare active vendor accounts with contract status.","evidence":["Contract owner assignment list","Contract amendment and renewal records","Comparison of the vendor user account list with active contracts","Termination and exit checklists"],"findings":["The remote access account of a vendor whose contract has expired remains active.","Because contract end dates are not tracked, some contracts were automatically renewed without evaluation."],"iso":["5.19","5.20","5.22"],"clauses":[],"itgc":""},
{"code":"APO10.04","name":"Manage vendor risk.","title":"Assessing vendor risk and reviewing third-party assurance","expectation":"For critical vendors, information security, financial stability, continuity, concentration and supply chain risks are assessed at intervals defined by the organization, and the results are recorded in the risk register. Independent assurance reports (e.g., SOC 2 report, ISO/IEC 27001 certificate) are reviewed, and the complementary controls assigned to the user entity in the report are implemented within the organization.","design":"Evaluate whether the vendor risk assessment method is linked to the criticality class and mandates the review of assurance reports.","operating":"For selected critical vendors, inspect the current risk assessment, the appropriateness of the assurance report's scope and period, the handling of exceptions noted in the report and the implementation of complementary controls.","evidence":["Vendor risk assessment reports","Independent assurance reports and review notes","Complementary user entity controls mapping","Exit and continuity plans for critical vendors"],"findings":["An assurance report was obtained, but its scope, period and exceptions were not evaluated.","No alternative or exit plan exists for a single-source critical service."],"iso":["5.19","5.21","5.23","5.30"],"clauses":[],"itgc":""},
{"code":"APO10.05","name":"Monitor vendor performance and compliance.","title":"Holding vendors to their contractual performance and obligations","expectation":"Vendor performance is measured against contractual service levels and security obligations at intervals defined by the organization and is discussed in review meetings. In the event of non-compliance, service credit, corrective action or escalation mechanisms are applied and the results are recorded.","design":"Evaluate whether performance indicators, reporting frequency and the steps to follow in the event of non-compliance are defined in contracts and procedures.","operating":"Compare the periodic performance reports of selected critical vendors against contractual targets and, where possible, against the organization's own monitoring data; inspect the action and closure records for breaches.","evidence":["Vendor performance reports and scorecards","Periodic vendor review meeting minutes","Service credit or penalty application records","Vendor review or audit reports"],"findings":["Performance reports provided by the vendor are accepted without independent validation by the organization.","Service credits defined in the contract were not claimed despite recurring breaches."],"iso":["5.22"],"clauses":[],"itgc":""}
]},
{"objective":"APO11","purpose":"Quality management ensures that IT solutions and services consistently meet business expectations rather than leaving this to chance. Defined standards, measurements and reviews enable early detection of defects, reduce rework and help maintain user confidence.","auditFocus":"The auditor tests whether the quality management system is embedded in critical processes such as development, change and service delivery rather than existing only on paper. The auditor looks for evidence that quality measurements, review results and improvement actions are tracked through to closure.","keyRisks":["Defective solutions being deployed to production due to inconsistent application of quality standards","User complaints not being fed back into quality processes","Quality reviews remaining a formality and the same errors recurring"],"practices":[
{"code":"APO11.01","name":"Establish a quality management system (QMS).","title":"Putting a documented, approved quality management system in place for IT","expectation":"The organization establishes a documented quality management system for IT activities that defines its scope, quality policy and objectives, roles and core processes. The system is approved by senior management and is aligned with the enterprise quality framework, where one exists.","design":"Evaluate whether the scope of the quality management system includes critical IT processes and whether quality roles and objectives are defined in measurable terms.","operating":"Inspect the approval and version history of quality documents; verify that the defined roles have actually been assigned and that quality objectives were measured during the period.","evidence":["Approved quality policy and quality manual","Quality roles and assignment records","Quality objectives and measurement results","Document version and approval history"],"findings":["Quality documents exist but do not cover IT service delivery processes.","Quality objectives are defined, but no measurement data is collected against them."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO11.02","name":"Focus quality management on customers.","title":"Running quality management with a user and customer focus","expectation":"The quality expectations of internal and external customers are identified and reflected in acceptance criteria; customer satisfaction and complaints are measured regularly. The results are used when reviewing quality objectives and priorities.","design":"Evaluate whether a mechanism exists to translate customer requirements into acceptance criteria and to feed customer feedback into the quality plan.","operating":"For selected projects or services, inspect whether acceptance criteria are documented and the acceptance decision was made against them, and whether complaint analyses are addressed in quality reviews.","evidence":["Customer acceptance criteria and acceptance records","Satisfaction measurement results","Complaint categorization and trend analyses"],"findings":["Acceptance tests were completed without user-defined criteria.","Complaint trends are not included on the quality review agenda."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO11.03","name":"Manage quality standards, practices and procedures and integrate quality management into key processes and solutions.","title":"Managing quality standards and embedding them in core processes","expectation":"Requirements such as coding standards, document templates and quality gates are defined for development, testing, change and service delivery processes and are built into the process steps. Standards are updated at intervals defined by the organization and communicated to the relevant personnel.","design":"Evaluate whether quality gates are defined as mandatory steps in the process flow and whether bypassing them requires a documented exception approval.","operating":"For a risk-based selection of projects or releases completed during the period, inspect the quality gate records (review, test result, approval); verify that exceptions were approved.","evidence":["Quality standards and template library","Quality gate checklists and approvals","Code and document review records","Approvals of exceptions to standards"],"findings":["Quality gates were bypassed without approval due to time pressure.","Coding standards do not cover the current technologies in use, and teams follow different practices."],"iso":["8.25","8.28"],"clauses":[],"itgc":"sdlc"},
{"code":"APO11.04","name":"Perform quality monitoring, control and reviews.","title":"Measuring quality and independently reviewing work products","expectation":"Process and product quality is monitored using metrics defined by the organization (e.g., defect rates, rework, defects found in production), and planned quality reviews are performed. Results are reported to those responsible and corrective actions are opened for nonconformities.","design":"Evaluate whether the scope of the quality review plan, the independence of reviewers and the method for recording nonconformities are defined.","operating":"Inspect selected quality review reports from the period; verify that the nonconformities identified were transferred to the corrective action log and tracked.","evidence":["Quality review plan and reports","Quality metric dashboards","Nonconformity and corrective action records"],"findings":["Reviews are performed by the same team that carried out the work under review, so independence is not achieved.","A significant portion of nonconformity records remain open past their target dates."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO11.05","name":"Maintain continuous improvement.","title":"Turning quality lessons into measured, lasting improvements","expectation":"Improvement opportunities arising from quality measurements, audit findings, incidents and feedback are consolidated in a single register, prioritized and assigned owners. The effect of improvements is measured after implementation, and successful practices are incorporated into the standards.","design":"Evaluate whether the steps for evaluating and approving improvement proposals and for measuring their effectiveness are defined.","operating":"For closed items selected from the improvement register, inspect evidence of implementation and of post-implementation impact measurement.","evidence":["Continuous improvement register","Improvement prioritization decisions","Post-implementation impact measurements","Updated versions of standards and procedures"],"findings":["Improvement items were closed, but their effectiveness was not measured.","Issues with the same root cause are repeatedly opened as separate records."],"iso":[],"clauses":[],"itgc":""}
]},
{"objective":"APO12","purpose":"IT risks can directly affect the organization's financial position and reputation through cyberattacks, system outages, project failures and compliance breaches. This objective ensures that IT-related risks are systematically identified, analyzed, compared against the enterprise risk appetite and responded to.","auditFocus":"The auditor tests whether the IT risk methodology is consistent with enterprise risk management, whether the risk register is current and has assigned owners, and whether risk acceptances are approved by authorized individuals. The auditor also verifies that actual incidents and audit findings are fed back into the risk profile.","keyRisks":["Significant IT risks not being identified or having become outdated","Risk acceptances granted by unauthorized individuals or without an expiry date","Risk actions not being implemented, giving management misleading assurance"],"practices":[
{"code":"APO12.01","name":"Collect data.","title":"Gathering the incident, loss and threat data that informs IT risk","expectation":"The organization regularly collects risk-related data, such as internal and external events, loss data, threat intelligence, vulnerability scan results and audit findings, from defined sources. The data is stored using a consistent classification and is available for use in risk analysis.","design":"Evaluate whether a method exists that defines which risk data is collected, from which source, how often and by whom.","operating":"Verify that a selection of significant incidents and audit findings from the period was transferred to the risk database and classified.","evidence":["List of risk data sources","Incident and loss database records","Threat intelligence and vulnerability summary reports","Records linking audit findings to the risk register"],"findings":["Significant security incidents are not used as input to risk assessment.","Risk data is maintained by different units under different classifications and cannot be consolidated."],"iso":["5.7","5.27"],"clauses":["8.2"],"itgc":""},
{"code":"APO12.02","name":"Analyze risk.","title":"Rating IT risks consistently for likelihood, impact and risk appetite","expectation":"IT risks are assessed for likelihood and impact according to a methodology approved by the organization; risk scenarios are linked to business processes and information assets. The results are compared against the enterprise risk appetite and tolerance and are refreshed at intervals defined by the organization or upon significant changes.","design":"Evaluate whether the risk methodology includes scales, criteria and risk appetite definitions and is consistent with enterprise risk management.","operating":"For records selected from the risk register, test the compliance of the scoring with the methodology through recalculation; check that significant changes, such as new systems or outsourcing, triggered a reassessment.","evidence":["Approved risk assessment methodology","Risk assessment working papers","Risk appetite and tolerance statement","Post-change reassessment records"],"findings":["Risk scores were assigned without support from the criteria in the methodology.","The related risk assessment was not updated following a major system transformation."],"iso":[],"clauses":["6.1","8.2"],"itgc":""},
{"code":"APO12.03","name":"Maintain a risk profile.","title":"Keeping the IT risk profile current","expectation":"The organization's IT risk profile is maintained in an integrated manner together with the risk register, related controls, risk owners and current status information. Key risk indicators (KRIs) are defined and threshold breaches are reported to the relevant owners.","design":"Evaluate whether the mandatory fields of the risk register (owner, related control, residual risk, review date) and the KRI thresholds are defined.","operating":"For records selected from the risk register, inspect whether review dates are current, whether the risk owner is still in role and authorized, and the responses to KRI threshold breaches.","evidence":["IT risk register export","KRI definitions and periodic values","Risk owner confirmation records","Risk and control mapping matrix"],"findings":["Individuals who have left the organization are listed as risk owners in the risk register.","No action record was created despite KRI thresholds being exceeded."],"iso":[],"clauses":["8.2"],"itgc":""},
{"code":"APO12.04","name":"Articulate risk.","title":"Reporting risks to stakeholders in an understandable way","expectation":"IT risk status is reported to senior management and the relevant committees at a frequency defined by the organization, expressed in terms of business impact and including trends and the position relative to risk appetite. Critical risks and situations exceeding risk appetite are escalated without waiting for the next reporting cycle.","design":"Evaluate whether the reporting content, recipients and escalation criteria are defined.","operating":"Check consistency by comparing the risk reports for the period with the risk register; confirm from committee minutes that records exceeding risk appetite were communicated to management.","evidence":["Management and committee risk reports","Risk discussions in committee minutes","Escalation records"],"findings":["The report presented to management omits some of the high risks recorded in the risk register.","Risk reports are prepared in technical terms and do not explain the business impact."],"iso":[],"clauses":["9.3"],"itgc":""},
{"code":"APO12.05","name":"Define a risk management action portfolio.","title":"Deciding how each risk is treated and who may accept it","expectation":"For risks exceeding risk appetite, the response option to be applied (mitigation, transfer, avoidance or acceptance) is determined; actions are managed as a portfolio in terms of cost-benefit and priority. Risk acceptances are approved by authorized individuals, with a documented rationale and for a defined period.","design":"Evaluate whether risk response options, the acceptance authority matrix and the tracking of actions with owner and target date information are defined.","operating":"For risk acceptances selected from those granted during the period, inspect the approval authority, rationale and validity period; analyze delays in the action portfolio.","evidence":["Risk treatment and action plan","Risk acceptance forms and approvals","Acceptance authority matrix","Action tracking reports"],"findings":["Risk acceptances were granted without an expiry date and have not been reassessed.","Actions are defined for some high risks, but no budget or owner has been assigned."],"iso":[],"clauses":["6.1","8.3"],"itgc":""},
{"code":"APO12.06","name":"Respond to risk.","title":"Responding promptly to materialized risks","expectation":"When a risk materializes (incident, loss or control failure), defined response plans are activated to limit the impact and the relevant stakeholders are informed. Post-incident reviews identify the root cause, and the risk profile and controls are updated accordingly.","design":"Evaluate whether response plans for risk events, communication rules and post-incident review steps are defined and linked to incident management.","operating":"For significant incidents selected from the period, inspect the response records, the post-incident review report and the updates made to the risk register.","evidence":["Incident response records","Post-incident review reports","Post-incident risk register updates","Response plans and exercise records"],"findings":["A root cause analysis was performed after a significant outage, but the findings were not reflected in the risk register.","Contact information in the response plans is not up to date."],"iso":["5.24","5.26","5.27"],"clauses":[],"itgc":""}
]},
{"objective":"APO13","purpose":"Information security supports business continuity and stakeholder trust by protecting the confidentiality, integrity and availability of the organization's information assets. This objective ensures that security is managed not through fragmented technical measures but through an information security management system (ISMS) that is owned by management, risk-based and continually improving.","auditFocus":"The auditor tests whether the ISMS scope includes critical processes and systems, whether the risk treatment plan is linked to actual risks and whether management reviews produce concrete decisions. Through inspection and sampling, the auditor identifies gaps between policies on paper and actual practice.","keyRisks":["The ISMS scope excluding critical systems","Actions in the risk treatment plan not being implemented or being repeatedly postponed","Management holding an unrealistic perception of the security posture"],"practices":[
{"code":"APO13.01","name":"Establish and maintain an information security management system (ISMS).","title":"Setting up a management-owned security management system with a clear scope","expectation":"The ISMS scope is determined considering the organization's internal and external context and the expectations of interested parties; an information security policy and an allocation of roles approved by senior management exist. The policy and scope are reviewed at intervals defined by the organization and upon significant changes.","design":"Evaluate whether the scope document explicitly includes critical processes, locations, systems and external services, and whether the policy is supported by management approval and role definitions.","operating":"Compare the inventory of critical applications and infrastructure with the ISMS scope; inspect the most recent review, approval and communication records for the policy and scope.","evidence":["ISMS scope document","Approved information security policy","Security roles and responsibilities definitions","Policy review and communication records"],"findings":["A critical cloud-hosted application has been excluded from the ISMS scope.","The policy has been approved, but there is no record that it was communicated to personnel."],"iso":["5.1","5.2"],"clauses":["4.3","5.2","5.3"],"itgc":""},
{"code":"APO13.02","name":"Define and manage an information security risk treatment plan.","title":"Planning, approving and tracking security risk treatment actions","expectation":"Controls selected based on the results of the information security risk assessment are consolidated in a risk treatment plan with responsible parties, resources and target dates, and the plan is consistent with the Statement of Applicability (SoA). The plan is approved by risk owners and its progress is monitored regularly.","design":"Evaluate whether the risk treatment plan is traceably linked to the risk register and the SoA and whether residual risks are accepted by the risk owners.","operating":"For a risk-based selection of actions from the plan, inspect evidence of implementation (configuration output, procedure, record) using read-only methods; verify that overdue actions were escalated and that residual risk approvals exist.","evidence":["Information security risk treatment plan","Statement of Applicability (SoA)","Residual risk acceptance approvals","Action progress reports"],"findings":["No evidence of implementation can be found for some controls marked as “implemented” in the SoA.","A significant portion of the actions in the risk treatment plan are past their target dates and have not been rescheduled."],"iso":[],"clauses":["6.1","8.3"],"itgc":""},
{"code":"APO13.03","name":"Monitor and review the information security management system (ISMS).","title":"Measuring security performance and driving management decisions on the ISMS","expectation":"ISMS performance is monitored through defined security metrics, internal audits and incident analyses; the results are presented for senior management review at intervals defined by the organization. Decisions and corrective actions arising from the review are assigned owners and tracked.","design":"Evaluate whether security metrics, the internal audit program and the inputs to management review are defined.","operating":"Inspect the management review minutes and internal audit reports for the period; verify with evidence the closure status of the resulting decisions and nonconformities.","evidence":["Security metric reports","ISMS internal audit program and reports","Management review minutes","Corrective action records"],"findings":["A management review was held, but the minutes contain no decisions or actions.","Corrective actions for internal audit findings were closed without a root cause analysis."],"iso":["5.35","5.36"],"clauses":["9.1","9.2","9.3"],"itgc":""}
]},
{"objective":"APO14","purpose":"Data is the common raw material for decision-making, reporting, regulatory compliance and digital services. Data with unclear ownership, unmeasured quality or an unmanaged life cycle leads to flawed decisions, reporting errors and increased security and privacy risks due to unnecessary retention. This objective ensures that data is managed as an enterprise asset.","auditFocus":"The auditor tests whether ownership, definition and quality controls exist for critical data assets and whether data is managed according to defined rules from creation to destruction. In particular, the auditor verifies with evidence the retention and destruction practices and that restore-from-backup tests are actually performed.","keyRisks":["Inconsistent or inaccurate data flowing into critical reports and decisions","Data being retained longer than necessary or destroyed prematurely","Permanent data loss due to backups that cannot be restored"],"practices":[
{"code":"APO14.01","name":"Define and communicate the organization's data management strategy and roles and responsibilities.","title":"Defining and communicating the data management strategy, roles and responsibilities","expectation":"The organization has a data management strategy aligned with business objectives and defined roles such as data owner, data steward and technical data custodian. Owners are assigned for critical data domains; the strategy and roles have been communicated to the relevant stakeholders.","design":"Evaluate whether a structure exists in which data governance roles are defined with their authorities and responsibilities and critical data domains are mapped to owners.","operating":"For selected critical data domains, inspect whether owner assignments are current and whether owners actually perform the approvals and reviews required by the role.","evidence":["Approved data management strategy","Data governance role definitions and RACI matrix","Data domain to data owner mapping list","Data governance board minutes"],"findings":["No business-side data owner has been assigned for critical customer data, and responsibility has in practice been left to IT.","A strategy document has been prepared but has not been approved or communicated."],"iso":["5.9"],"clauses":[],"itgc":""},
{"code":"APO14.02","name":"Define and maintain a consistent business glossary.","title":"Establishing a single, agreed set of business term definitions","expectation":"A business glossary exists containing single, approved definitions for critical business terms and indicators (e.g., “active customer”, “net sales”), and each term has an owner. Definition changes are approved in a controlled manner and communicated to the reporting and analytics teams.","design":"Evaluate whether the process for adding, changing and approving glossary terms and the ownership of terms are defined.","operating":"Compare the calculation logic of indicators selected from critical management reports with the glossary definitions; inspect the approval records for glossary changes.","evidence":["Business glossary export","Term ownership list","Definition change approval records","Report indicator definitions and calculation logic"],"findings":["The same indicator is calculated using different definitions in different reports.","Some glossary terms have no owner and are out of date."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO14.03","name":"Establish the processes and infrastructure for metadata management.","title":"Recording where critical data comes from, what it means and who owns it","expectation":"Technical and business metadata for critical data assets (source system, data lineage, classification, owner) is maintained in a data catalog or metadata repository. Metadata is kept current through updates triggered by system changes and through periodic checks at intervals defined by the organization.","design":"Evaluate whether the metadata collection method (automated scanning, manual entry), the responsible parties and the link to change management are defined.","operating":"Compare the catalog metadata of selected critical data sets with the actual structure and classification label in the source system.","evidence":["Data catalog or metadata repository records","Data lineage diagrams","Data classification labels","Metadata update records"],"findings":["Table structures in the catalog do not reflect recent changes in the production system.","Fields containing personal data are not classified in the catalog."],"iso":["5.12","5.13"],"clauses":[],"itgc":""},
{"code":"APO14.04","name":"Define a data quality strategy.","title":"Setting data quality dimensions, thresholds and accountabilities","expectation":"The organization has a data quality strategy that defines, for critical data, quality dimensions such as accuracy, completeness, consistency and timeliness, acceptable thresholds and responsibilities. Thresholds are defined by the organization together with the data owners and are prioritized according to business impact.","design":"Evaluate whether quality dimensions, measurement rules and thresholds are linked to critical data domains and approved by their owners.","operating":"For selected critical data domains, inspect whether defined quality rules and thresholds exist and whether measurement results are reported.","evidence":["Data quality strategy or policy","Quality rules and threshold definitions","Data owner approvals","Data quality dashboard"],"findings":["No quality thresholds are defined; issues are identified only through user complaints.","The strategy covers only a single system; other critical data sources are excluded."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO14.05","name":"Establish data profiling methodologies, processes and tools.","title":"Profiling data to detect anomalies before they cause problems","expectation":"Critical data sets are profiled using defined methods and tools to reveal anomalies such as null values, outliers, format errors and duplicate records. Profiling is performed upon triggers such as the integration of a new data source, a data migration or a quality issue, and at intervals defined by the organization.","design":"Evaluate whether the profiling scope, the tools to be used, the triggers, access restrictions on personal data and the recipients of the results are defined.","operating":"For selected data migration and integration projects from the period, inspect the profiling outputs and the actions taken based on them; check that profiling was performed on masked data where possible.","evidence":["Profiling methodology","Profiling tool outputs and reports","Pre-migration profiling results","Anomaly tracking records"],"findings":["Source data was not profiled prior to a major data migration.","Profiling was performed on production data containing personal data with access rights broader than necessary."],"iso":["8.11"],"clauses":[],"itgc":""},
{"code":"APO14.06","name":"Ensure a data quality assessment approach.","title":"Measuring data quality regularly and acting on threshold breaches","expectation":"Critical data is measured against quality rules in a regular and repeatable manner; the results are compared with thresholds and reported to data owners. Root cause analysis is performed for threshold breaches and improvement actions are tracked.","design":"Evaluate whether the frequency and scope of the assessment, the reporting of results and the steps to follow upon threshold breaches are defined.","operating":"For selected quality assessment results from the period, verify the results by reperforming the measurement rules using read-only queries; check that threshold breaches are linked to action records.","evidence":["Periodic data quality assessment reports","Quality rule execution logs","Threshold breach action records"],"findings":["Quality measurements are performed, but the results are not communicated to data owners.","Measurement rules produce misleading results because they were not updated after source system changes."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO14.07","name":"Define the data cleansing approach.","title":"Correcting data in a controlled, approved and traceable way","expectation":"The correction of inaccurate or duplicate data follows a controlled approach that specifies by whom, under what authority, based on what evidence and by what method (correction at source, bulk update) it is performed. Before bulk corrections, a backup is taken, data owner approval is obtained and the changes are retained with an audit trail.","design":"Evaluate whether data corrections are defined with requirements for approval, segregation of duties between requester and implementer, and an audit trail, and whether direct database interventions are restricted.","operating":"Obtain the complete list of bulk data corrections and direct data interventions for the period and, for a risk-based selection, inspect evidence of approval, backup and post-correction validation.","evidence":["Data cleansing procedure","Bulk data correction requests and approvals","Database change and audit logs","Post-correction validation results"],"findings":["Unapproved direct SQL updates were made to production data.","An erroneous update could not be reversed because no backup was taken before the bulk correction."],"iso":["8.15"],"clauses":[],"itgc":"change"},
{"code":"APO14.08","name":"Manage the life cycle of data assets.","title":"Controlling data from creation to destruction","expectation":"Data assets are managed through the creation, use, sharing, archiving and destruction stages under rules appropriate to their classification, and the data inventory shows these stages and the responsible parties. The copying of sensitive data to test environments, its sharing with external parties and its destruction are controlled through defined approvals and technical measures.","design":"Evaluate whether life cycle rules (sharing, masking, destruction method) are defined by data class and linked to the data inventory.","operating":"For selected critical data sets, inspect the inventory record, the masking status of copies in test environments and the destruction records; personal data in audit evidence is retained in masked form.","evidence":["Data inventory and classification records","Data sharing approvals","Test data masking evidence","Destruction records"],"findings":["Unmasked real customer data exists in the test environment.","The life cycle stage and owner are not defined for many data sets in the data inventory."],"iso":["5.12","8.10","8.11","8.33"],"clauses":[],"itgc":""},
{"code":"APO14.09","name":"Support data archiving and retention.","title":"Retaining, archiving and disposing of data according to an approved schedule","expectation":"The organization has an approved retention schedule, based on business, contractual and regulatory requirements, that specifies retention periods by data type. Archived data is retained with its integrity preserved and in a form that remains readable when needed; data whose retention period has expired is destroyed in a controlled and recorded manner.","design":"Evaluate whether a structure exists in which the retention schedule is linked to the data inventory, archive access is restricted and destruction requires approval and recording.","operating":"For selected data types, compare the actual retention periods in systems with the schedule; inspect the approvals and records for destruction activities during the period and the results of archive retrieval attempts.","evidence":["Approved data retention schedule","Archive system configuration and access lists","Destruction approvals and records","Archive retrieval test records"],"findings":["Personal data whose retention period has expired is kept in systems without being destroyed.","Data archived in legacy formats cannot be read with current tools."],"iso":["5.33","5.34","8.10"],"clauses":[],"itgc":""},
{"code":"APO14.10","name":"Manage data backup and restore arrangements.","title":"Ensuring critical data is backed up and can be restored","expectation":"For critical systems and data, the backup scope, frequency, retention period and recovery objectives (RPO/RTO) are defined by the organization based on business requirements. Backup jobs are monitored, failed jobs are followed up, backups are protected against unauthorized access and modification, and restore tests are performed as planned.","design":"Evaluate whether the backup policy covers the critical system inventory and mandates the handling of failed backup alerts and periodic restore testing.","operating":"Obtain the job history for the period from the backup tool and inspect the follow-up of failed jobs; for selected critical systems, verify the restore test records and results. The auditor does not perform restores in the production environment.","evidence":["Backup policy and scope list","Backup tool job history report","Failed backup incident records","Restore test records"],"findings":["A newly deployed server has not been added to the backup scope.","Restore tests were planned but not performed during the period."],"iso":["8.13","5.30"],"clauses":[],"itgc":"operations"}
]}
]
);
